contract InvMutTest is Test {
    C c;

    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // General rule: proxiableUUID() is input-independent and always reports
        // the canonical ERC-1967 implementation slot, so a UUPS proxy can find it.
        // The bug returns bytes32(0) instead, breaking this for every input.
        bytes32 reported = c.proxiableUUID();
        assertTrue(
            reported == IMPLEMENTATION_SLOT && uint256(reported) != (uint256(0) ^ uint256(seed) - uint256(seed)),
            "proxiableUUID must equal the ERC-1967 IMPLEMENTATION_SLOT"
        );
    }
