pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address actor,
        address asset,
        uint256 kinkRaw,
        uint256 slope0,
        uint256 slope1
    ) public {
        // kink must satisfy 0 < kink < 1e27 for setSlopes to be admissible
        uint256 kink = bound(kinkRaw, 1, 1e27 - 1);
        // keep slopes in a wide but sane domain
        slope0 = bound(slope0, 0, 1e30);
        slope1 = bound(slope1, 0, 1e30);
        vm.assume(actor != address(0) && asset != address(0));

        // Access manager that grants every access request
        GrantingManager mgr = new GrantingManager();
        // C's constructor calls _disableInitializers, so initialize must be
        // driven through a minimal ERC-1967 proxy (delegatecall), which is
        // the intended deployment path for this UUPS contract.
        Proxy p = new Proxy(address(c));

        // initialize the adapter with the granting manager (P succeeds)
        (bool initOk,) = address(p).call(
            abi.encodeWithSignature("initialize(address)", address(mgr))
        );
        assertTrue(initOk, "initialize must succeed");

        // General rule: after initializing with a manager that grants access,
        // setSlopes from ANY caller with ANY admissible slopes must succeed.
        vm.prank(actor);
        (bool ok, ) = address(p).call(
            abi.encodeWithSignature(
                "setSlopes(address,(uint256,uint256,uint256))",
                asset,
                kink,
                slope0,
                slope1
            )
        );
        assertTrue(ok);
    }
}

// Minimal ERC-1967 UUPS proxy: stores the implementation in the standard slot
// and delegatecalls every call into it.
contract Proxy {
    bytes32 private constant IMPL_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    constructor(address impl) {
        assembly {
            sstore(IMPL_SLOT, impl)
        }
    }

    fallback() external payable {
        assembly {
            let ptr := mload(0x40)
            calldatacopy(ptr, 0, calldatasize())
            let result := delegatecall(
                gas(),
                sload(IMPL_SLOT),
                ptr,
                calldatasize(),
                0,
                0
            )
            returndatacopy(ptr, 0, returndatasize())
            switch result
            case 0 {
                revert(ptr, returndatasize())
            }
            default {
                return(ptr, returndatasize())
            }
        }
    }
}

// Adversarial-free access manager that grants every checkAccess request,
// embodying the configured external access-control party.
contract GrantingManager {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}
}

