contract InvMutTest is Test {
    C c;
    address proxy;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 kink, uint256 slope0, uint256 slope1, address caller) public {
        kink = bound(kink, 1, 1e27 - 1);
        slope0 = bound(slope0, 0, 1e30);
        slope1 = bound(slope1, 0, 1e30);
        vm.assume(caller != address(0));

        // fresh proxy per run so `initialize` is admissible (implementation's constructor disables its own initializers)
        Proxy p = new Proxy(address(c));
        proxy = address(p);

        // an access manager that grants every checkAccess request
        GrantManager mgr = new GrantManager();

        vm.prank(caller);
        (bool initOk, ) = proxy.call(
            abi.encodeWithSelector(C.initialize.selector, address(mgr))
        );
        assertTrue(initOk, "initialize with a valid manager should succeed");

        C.SlopeData memory slopes = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        vm.prank(caller);
        (bool ok, ) = proxy.call(
            abi.encodeWithSelector(C.setSlopes.selector, address(0x1234), slopes)
        );

        // General rule: after a successful initialize with a granting access manager,
        // ANY access-gated call from ANY caller must succeed on the correct C.
        // The mutant never stores the manager, so checkAccess reverts and ok is false.
        assertTrue(ok, "gated call must succeed when the stored manager grants access");
    }
}

