pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address admin) public {
        vm.assume(admin != address(0));

        // C's constructor disables initializers, so drive it through a minimal proxy
        // whose (empty) storage is where the initializer latch lives.
        bytes memory initCode = abi.encodePacked(
            hex"3d602d80600a3d3981f3363d3d373d3d3d363d3d545af43d82803e903d91602b57fd5bf3",
            abi.encode(c)
        );
        address proxy;
        assembly {
            proxy := create(0, add(initCode, 0x20), mload(initCode))
        }

        (bool ok1, ) = proxy.call(abi.encodeCall(C.initialize, (admin)));
        (bool ok2, ) = proxy.call(abi.encodeCall(C.initialize, (admin)));

        // Reference: first initialize succeeds, second reverts (initializer latch).
        // Mutant: _initialized is never set, so the second initialize also succeeds.
        assertTrue(ok1 && !ok2);
    }
}

