        vm.assume(actor != address(0));
        vm.assume(admin != address(0));
        warpTo = bound(warpTo, 1, type(uint256).max / 2);

        vm.warp(warpTo);
        vm.prank(actor);
        bool firstOK;
        try c.initialize(admin) {
            firstOK = true;
        } catch {
            firstOK = false;
        }

        vm.roll(block.number + 1);
        vm.prank(actor);
        bool secondOK;
        try c.initialize(admin) {
            secondOK = true;
        } catch {
            secondOK = false;
        }

        assertTrue(!firstOK || !secondOK, "re-initialized after successful initialize");
    }
}

