pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address admin) public {
        // C's constructor calls _disableInitializers(), so drive it through an
        // EIP-1167 minimal proxy whose storage starts empty (initialized == 0).
        address impl = address(c);
        address proxy;
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000000000000000000000)
            mstore(add(ptr, 20), shl(96, impl))
            mstore(add(ptr, 40), 0x5af43d82803e903d91602b57fd5bf30000000000000000000000000000000000)
            proxy := create(0, ptr, 45)
        }

        // First initialize on a fresh proxy: any admin is admissible.
        bytes memory payload = abi.encodeWithSelector(C.initialize.selector, admin);
        (bool ok1, ) = proxy.call(payload);
        vm.assume(ok1);

        // RULE: once initialize() has succeeded, the initializer latch must be
        // set, so ANY subsequent initialize() (same admin or not) must revert.
        (bool ok2, ) = proxy.call(payload);

        assertTrue(!ok2, "initialize must be one-shot: second call must revert");
    }
}
